function currentPlan(){let start=workspace.profile.planStart;const elapsed=Math.floor((new Date(today()+'T12:00:00Z')-new Date(start+'T12:00:00Z'))/86400000);if(elapsed>27)start=addDays(today(),-(elapsed%28));return buildFourWeekPlan(workspace,{startDate:start});}
