async function api(path, options={}) {
  let response;try{response = await fetch('/api/v2'+path, {credentials:'same-origin',signal:AbortSignal.timeout?.(90_000),...options,headers:{...(options.body && typeof options.body === 'string' ? {'Content-Type':'application/json'} : {}),...options.headers}});}catch(error){throw new Error(error.name==='TimeoutError'?'연결 시간이 초과됐어요. 저장된 지점부터 다시 시도할 수 있어요.':'서버에 연결하지 못했어요. 네트워크를 확인하고 다시 시도해 주세요.');}
  const data = await response.json().catch(()=>({error:'서버 응답을 읽지 못했어요. 연결을 확인해 주세요.'}));
  if (!response.ok) { const error=new Error(data.error || data.message || '요청을 완료하지 못했어요.'); error.status=response.status; error.code=data.code; throw error; }
  return data;
}
