async function load() { [workspace, {jobs}, {uploads:pendingUploads}, {imports}, analysisStatus] = await Promise.all([api('/workspace'),api('/jobs'),api('/uploads'),api('/imports'),api('/status')]); }
async function changeWorkspace(update) {
  for(let attempt=0;attempt<2;attempt++) {
    const latest=await api('/workspace'); const next=structuredClone(latest); update(next);
    try { workspace=await api('/workspace',{method:'PUT',body:JSON.stringify(next)}); render(); return; } catch(error) { if(error.status!==409 || attempt) throw error; }
  }
}
const observationsFor = videoId => workspace.analyses.filter(a=>!videoId || a.videoId===videoId).flatMap(a=>a.result.identified ? a.result.observations.map((o,i)=>({...o,id:`${a.id}-${i}`,videoId:a.videoId,analysisId:a.id})) : []);
const latestVideo = () => [...workspace.videos].sort((a,b)=>(b.context?.matchDate||b.addedAt.slice(0,10)).localeCompare(a.context?.matchDate||a.addedAt.slice(0,10))||b.addedAt.localeCompare(a.addedAt))[0];
const newestJob = videoId => jobs.filter(j=>!videoId || j.videoId===videoId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];
function statusInfo(job) {
  if(!job) return {label:'저장 완료',class:'neutral',detail:'선수를 지정하고 자동 분석을 시작해 주세요.',percent:0};
  const stage=job.stage || job.status;
  const labels={queued:'분석 대기',probing:'영상 확인',scanning:'선수 탐색',analyzing:'플레이 분석',completed:'분석 완료',not_found:'선수 확인 보류',blocked:'서비스 복구 대기',quota:'서비스 복구 대기',failed:'분석 중단',cancelled:'분석 취소',running:'분석 중'};
  const p=job.progress || {};
  let percent=job.status==='completed'?100:stage==='scanning'?Math.round(10+50*(p.sampledCount||0)/Math.max(1,p.sampleCount||120)):stage==='analyzing'?Math.round(60+35*(p.completedCount||0)/Math.max(1,p.selectedCount||1)):job.status==='queued'?3:8;
  return {label:labels[stage] || labels[job.status] || '진행 중',class:['failed','cancelled','blocked'].includes(job.status)||stage==='not_found'?'warn':job.status==='completed'?'good':'neutral',percent,detail:job.status==='blocked'?'분석 서비스 사용 한도로 잠시 대기 중이에요. 원본과 진행 기록은 보관되어 있으며, 서비스가 복구되면 자동으로 이어갑니다.':job.error?.message || job.error?.error || (typeof job.error==='string'?job.error:'') || p.message || (job.status==='completed'?'근거 장면과 다음 실천을 확인해 보세요.':'화면을 닫아도 서버에서 계속 진행합니다.')};
}
function statusCard(job,compact=false) {
  const s=statusInfo(job);
  return `<section class="card status-card" aria-live="polite"><div class="card-head"><div class="inline">${icon('video')}<strong>${s.label}</strong></div><span class="badge ${s.class}">${job?.status==='completed'?icon('check',14):icon('clock',14)} ${job?'자동 분석':'원본 영상'}</span></div><p class="muted">${esc(s.detail)}</p>${job?.status==='blocked'&&job.retryAt?`<p class="source-note">다음 연결 확인: ${new Date(job.retryAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} 이후 · 화면을 열어 둘 필요 없어요.</p>`:''}${job && !['failed','cancelled','completed','blocked'].includes(job.status)?`<div class="progress" role="progressbar" aria-valuenow="${s.percent}" aria-valuemin="0" aria-valuemax="100" aria-label="분석 진행"><span style="width:${s.percent}%"></span></div>`:''}${!compact&&job&&['failed','cancelled'].includes(job.status)?button('저장된 지점부터 다시 시도','retry-job','secondary',`data-id="${esc(job.id)}"`):''}${!compact&&job&&['queued','running','blocked'].includes(job.status)?button('분석 취소','cancel-job','quiet',`data-id="${esc(job.id)}"`):''}</section>`;
}
